NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'Galatians'

CHAPTERS = {
    1: {
        1: 'Paulus, Apostel, nicht von Menschen, noch durch einen Menschen, sondern durch Jesus Christus und Gott Vater, Der Ihn von den Toten auferweckt hat,',
        2: 'Und alle Brüder, die bei mir sind, an die Gemeinden in Galatien.',
        3: 'Gnade euch und Friede von Gott dem Vater und unserem Herrn Jesus Christus,',
        4: 'Der Sich für unsere Sünden hingegeben hat, auf daß Er uns erlöse von der gegenwärtigen argen Welt nach dem Willen Gottes und unseres Vaters,',
        5: 'Welchem sei Ehre in alle Ewigkeit! Amen.',
        6: 'Mich wundert, daß ihr euch von dem, der euch zu Christus Gnade berufen hat, so bald habt abwenden lassen zu einem anderen Evangelium.',
        7: 'So es doch kein anderes gibt und nur etliche da sind, die euch verwirren und das Evangelium von Christus verkehren wollen.',
        8: 'Aber wenn auch wir oder ein Engel vom Himmel euch ein anderes Evangelium verkündigte, als wir euch verkündigt haben, der sei verflucht.',
        9: 'Wie ich schon gesagt, sage ich euch abermals: Wenn euch einer ein anderes Evan- gelium predigt, als ihr empfangen habt, der sei verflucht.',
        10: 'Rede ich jetzt Menschen oder Gott zu Dienst, oder suche ich Menschen zu gefallen? Wenn ich Menschen gefallen wollte, so wäre ich Christus Knecht nicht.',
        11: 'Ich tue euch aber kund, Brüder, daß das Evangelium, das von mir gepredigt worden, nicht menschlicher Art ist.',
        12: 'Denn ich habe es auch nicht von einem Menschen empfangen, noch erlernt, sondern durch die Offenbarung von Jesus Christus.',
        13: 'Denn ihr habt ja wohl von meinem Wandel im Judentum gehört, daß ich die Gemeinde von Christus über die Maßen verfolgte und zu zerstören suchte;',
        14: 'Und es im Judentum vielen meines Alters in meinem Volke zuvor tat und ein heftigerer Eiferer für meine väterlichen Überlieferungen ward.',
        15: 'Als es aber Gott wohlgefiel, Der mich von Mutterleibe an ausersehen und durch Seine Gnade berufen hat,',
        16: 'Seinen Sohn in mir zu offenbaren, daß ich Ihn unter den Heiden verkündigen sollte; so ging ich schnurstracks, ohne mit Fleisch und Blut zu Rate zu gehen,',
        17: 'Oder mich nach Jerusalem an die zu wenden, die vor mir Apostel waren, sondern begab mich nach Arabien und kehrte von da wieder gen Damaskus.',
        18: 'Dann nach drei Jahren zog ich hinauf nach Jerusalem, um Petrus kennenzulernen, und blieb bei ihm fünfzehn Tage.',
        19: 'Einen anderen Apostel bekam ich nicht zu Gesicht außer Jakobus, den Bruder des Herrn.',
        20: 'Was ich euch aber schreibe, siehe, bei Gott, ich lüge nicht.',
        21: 'Danach kam ich in die Gegenden von Syrien und Cilicien.',
        22: 'Ich war aber den christlichen Gemeinden in Judäa persönlich unbekannt.',
        23: 'Sie hatten nur von mir gehört: Der früher uns verfolgte, predigt jetzt den Glauben, den er weiland verstörte.',
        24: 'Und sie priesen Gott über mir.',
    },
    2: {
        1: 'Nach vierzehn Jahren zog ich abermals hinauf gen Jerusalem mit Barnabas, und nahm auch Titus mit.',
        2: 'Ich zog aber hinauf infolge einer Offenbarung und legte ihnen das Evangelium vor, das ich unter den Heiden verkündige, insbesondere aber den Angesehenen, daß ich nicht etwa vergeblich liefe oder gelaufen wäre.',
        3: 'Aber nicht einmal Titus, der mit mir war, obgleich er Grieche war, ward gezwungen, sich beschneiden zu lassen.',
        4: 'Es waren aber falsche Brüder eingeschlichen und hatten sich eingedrängt, um der Freiheit aufzulauern, die wir in Jesus Christus haben, auf daß sie uns wieder unter das Joch brächten.',
        5: 'Diesen gaben wir aber keinen Augenblick nach, daß wir uns unterwürfen, auf daß die Wahrheit des Evangeliums bei euch verbliebe.',
        6: 'Anlangend diejenigen, die obenan standen, - welcherlei sie früher gewesen, geht mich nicht an, Gott sieht die Person des Menschen nicht an - haben mir diese Oberen keine andere Weisung gegeben.',
        7: 'Sondern im Gegenteil, da sie sahen, daß mir das Evangelium an die Vorhaut, so wie Petrus an die Beschneidung anvertraut war;',
        8: 'Wie denn, Der mit Petrus kräftig gewesen ist für das Apostelamt unter der Beschneidung, auch mit mir kräftig war unter den Heiden;',
        9: 'Da erkannten die Gnade, die mir zuteil geworden, Jakobus und Kephas und Johannes, die als die Säulen angesehen waren, reichten mir und Barnabas die Rechte zur Gemeinschaft, daß wir für die Heiden und sie für die Beschneidung predigten;',
        10: 'Nur sollten wir der Armen gedenken, was ich auch fleißig getan habe.',
        11: 'Als aber Kephas nach Antiochien kam, widersprach ich ihm ins Angesicht, da er als verurteilt erschien.',
        12: 'Denn ehe etliche von Jakobus kamen, aß er mit den Heiden; da sie aber kamen, zog er sich zurück und sonderte sich ab, aus Furcht vor denen in der Beschneidung.',
        13: 'Und auch die übrigen Juden heuchelten mit ihm, also, daß auch Barnabas mit zur Heuchelei verleitet wurde.',
        14: 'Als ich aber sah, daß sie nicht auf geradem Wege nach der Wahrheit des Evangeliums wandelten, sprach ich zu Kephas, in aller Gegenwart: Wenn du, der du ein Jude bist, heidnisch, nicht jüdisch lebst, wie willst du die Heiden zwingen, jüdisch zu leben?',
        15: 'Wiewohl wir von Natur Juden und nicht von Heiden her Sünder sind,',
        16: 'Doch, weil wir wissen, daß der Mensch nicht durch die Werke des Gesetzes gerecht wird, sondern durch den Glauben an Jesus Christus, haben auch wir an Jesus Christus geglaubt, auf daß wir durch den Glauben an Christus gerechtfertigt würden und nicht durch des Gesetzes Werke; denn durch des Gesetzes Werke wird kein Fleisch gerechtfertigt werden.',
        17: 'Sollten wir aber, die wir in Christus suchen gerechtfertigt zu werden, selbst auch als Sünder erfunden werden? Ist darum Christus der Sünde Diener? Das sei ferne!',
        18: 'Denn wenn ich das, was ich zerstört hatte, wieder aufbaue, so erweise ich mich selbst als Übertreter.',
        19: 'Denn ich bin durch das Gesetz dem Gesetz gestorben, auf daß ich Gott lebete; ich bin mit Christus gekreuzigt.',
        20: 'Ich lebe, aber nicht mehr ich, wohl aber lebt Christus in mir. Was ich aber jetzt lebe im Fleische, lebe ich im Glauben an den Sohn Gottes, Der mich geliebt und Sich für mich hingegeben hat.',
        21: 'Nicht verwerfe ich die Gnade Gottes, denn wenn durch das Gesetz Gerechtigkeit kommt, so ist Christus ohne Grund gestorben.',
    },
    3: {
        1: 'O ihr unverständigen Galater! Wer hat euch bezaubert,',
        2: 'Dies nur wünschte ich von euch zu erfahren: Habt ihr den Geist empfangen durch des Gesetzes Werke, oder durch die Predigt des Glaubens?',
        3: 'Seid ihr so unverständig? Im Geist habt ihr angefangen und werdet jetzt mit dem Fleische zur Vollendung gebracht?',
        4: 'So viel habt ihr denn vergeblich erlitten? Ja, wenn es auch nur vergeblich wäre?',
        5: 'Der euch nun den Geist verleiht und Wunder unter euch wirkt,',
        6: 'Wie Abraham Gott glaubte und es ihm zur Gerechtigkeit angerechnet wurde;',
        7: 'So erkennt ihr nun, daß, die im Glauben sind, Abrahams Söhne sind.',
        8: 'Die Schrift aber hat vorausgesehen, daß Gott die Heiden durch den Glauben rechtfertigt, und verhieß dem Abraham: In dir sollen alle Heiden gesegnet werden!',
        9: 'Darum werden, die im Glauben sind, mit dem gläubigen Abraham gesegnet.',
        10: 'Denn diejenigen, die mit den Werken des Gesetzes umgehen, sind unter dem Fluche; denn es steht geschrieben: Verflucht ist jeder, der nicht an allem dem hält, was in dem Buche des Gesetzes geschrieben ist, auf daß er es tue.',
        11: 'Daß durch das Gesetz keiner vor Gott gerechtfertigt wird, ist offenbar, weil der durch den Glauben Gerechte leben wird.',
        12: 'Das Gesetz ist aber nicht vom Glauben her, sondern der sie tut, wird leben.',
        13: 'Christus hat uns vom Fluche des Gesetzes losgekauft, indem Er für uns zum Fluch geworden ist; denn es steht geschrieben: Der am Kreuz hängt, ist verflucht;',
        14: 'Auf daß der Segen Abrahams durch Jesus Christus auf die Heiden käme, damit wir die Verheißung des Geistes durch den Glauben empfingen.',
        15: 'Ich will nach Menschenweise reden, Brüder: Schon eines Menschen Bund, der rechtskräftig geworden, stößt niemand um, noch tut man etwas hinzu.',
        16: 'Nun sind dem Abraham und seinem Samen Verheißungen geworden. Es heißt nicht: den Samen, als ob von vielen, sondern dem Samen als von einem, und deinem Samen, welcher ist Christus.',
        17: 'Ich sage aber soviel: Den Bund, der von Gott auf Christus rechtskräftig geworden, macht das Gesetz, das vierhundertdreißig Jahre darauf gegeben worden ist, nicht ungültig, so daß es die Verheißung aufhöbe.',
        18: 'Denn wenn das Besitztum aus dem Gesetz kommt, so kommt es nicht mehr aus der Verheißung; Gott aber hat es dem Abraham durch die Verheißung geschenkt.',
        19: 'Was soll nun das Gesetz? Es war der Übertretungen wegen gegeben, bis der Same käme, dem die Verheißung geworden, und ist angeordnet von Engeln durch eines Vermittlers Hand.',
        20: 'Der Vermittler ist aber nicht für einen; Gott aber ist Einer.',
        21: 'Ist nun das Gesetz wider die Verheißungen Gottes? Das sei ferne! Wenn ein Gesetz gegeben wäre, das lebendig machen könnte, so käme allerdings aus dem Gesetz die Gerechtigkeit.',
        22: 'Nun hat aber die Schrift alles der Sünde unterworfen, auf daß die Verheißung durch den Glauben an Jesus Christus den Gläubigen gegeben würde.',
        23: 'Ehe denn der Glaube kam, wurden wir unter dessen Botmäßigkeit in Verschluß gehalten für den Glauben, der geoffenbart werden sollte.',
        24: 'Das Gesetz ist somit unser Zuchtmeister geworden für Christus, auf daß wir durch den Glauben gerechtfertigt würden.',
        25: 'Nun aber der Glaube gekommen ist, stehen wir nicht mehr unter dem Zuchtmeister.',
        26: 'Denn ihr seid alle Söhne Gottes durch den Glauben an Jesus Christus.',
        27: 'Denn wie viele euer auf Christus getauft sind, die haben Christus angezogen.',
        28: 'Da ist kein Jude, kein Grieche, da ist kein Knecht, kein Freier, da ist kein Mann, noch Weib: denn ihr alle seid eins in Jesus Christus.',
        29: 'Seid ihr aber Christi, so seid ihr ja Abrahams Samen, und Erben nach der Verhei-ßung.',
    },
    4: {
        1: 'Ich sage aber, solange der Erbe noch ein Kind ist, ist zwischen ihm und einem Knechte kein Unterschied, obgleich er Herr von allem ist.',
        2: 'Er steht unter Vormündern und Verwaltern bis zu der vom Vater bestimmten Zeit.',
        3: 'So waren auch wir, solange wir unmündig waren, unter den Buchstaben der Welt geknechtet.',
        4: 'Als aber die Zeit erfüllt ward, sandte Gott Seinen Sohn, von einem Weibe geboren, dem Gesetze untertan.',
        5: 'Auf daß Er die, so unter dem Gesetze waren, loskaufete, und wir die Kindschaft empfingen.',
        6: 'Weil ihr denn Kinder seid, hat Gott den Geist Seines Sohnes in eure Herzen gesendet, der da ruft: Abba, lieber Vater!',
        7: 'So bist du nun nicht mehr Knecht, sondern Sohn; so du aber Sohn bist, so bist du auch Erbe Gottes durch Christus.',
        8: 'Aber zu der Zeit, da ihr Gott nicht kanntet, dientet ihr denen, die von Natur nicht Götter sind.',
        9: 'Nun ihr aber Gott erkannt habt, ja vielmehr von Gott erkannt worden seid, wie wollt ihr euch denn wieder zu den schwachen und ärmlichen Anfängen zurückwenden und denselben wieder von neuem dienen?',
        10: 'Ihr haltet auf Tage, Neumonde und Feste und Sabbathjahre.',
        11: 'Ich fürchte für euch, daß ich möchte vergeblich an euch gearbeitet haben.',
        12: 'Werdet doch wie ich, weil auch ich wie ihr geworden bin, Brüder, ich bitte euch; ihr habt mir nichts zu Leide getan.',
        13: 'Ihr wisset, daß ich in der Schwachheit des Fleisches euch zuerst das Evangelium predigte;',
        14: 'Und daß ihr meine Probe nicht von euch gewiesen und verschmäht, sondern mich wie einen Engel Gottes, wie Jesus Christus selbst aufgenommen habt.',
        15: 'Wie war es aber, daß ihr euch so glücklich prieset? Ja, ich bezeuge euch, daß ihr, wo möglich, euch die Augen ausgerissen und mir gegeben hättet.',
        16: 'Bin ich denn euer Feind geworden, daß ich euch die Wahrheit vorhalte?',
        17: 'Sie beeifern sich um euch, nicht in guter Absicht, sondern wollen euch von mir ausschließen, so daß ihr um sie sollet eifern.',
        18: 'Es ist immerhin gut, wenn man sich um des Guten willen beeifert, und nicht bloß, wenn ich bei euch bin.',
        19: 'Meine Kindlein, die ich von neuem mit Schmerzen gebäre, bis daß Christus in euch eine Gestalt gewinne!',
        20: 'Ich wollte aber, ich wäre gleich bei euch und könnte in einem anderen Tone zu euch reden; denn ich bin an euch irre geworden.',
        21: 'Sagt mir, ihr, die ihr unter dem Gesetze sein wollt, hört ihr nicht das Gesetz?',
        22: 'Es steht ja geschrieben, daß Abraham zwei Söhne hatte, einen von der Magd, den anderen von der Freien.',
        23: 'Aber der von der Magd ist nach dem Fleische geboren, der von der Freien hingegen nach der Verheißung.',
        24: 'Diese Dinge sind vorbildlich, denn sie sind zwei Bünde; einer vom Berge Sinai her gebiert zur Knechtschaft, welcher ist Hagar.',
        25: 'Denn Hagar heißt der Berg Sinai in Arabien und kommt überein mit dem jetzigen Jerusalem, denn dieses ist in Dienstbarkeit mit seinen Kindern.',
        26: 'Aber das Jerusalem, das droben ist, ist die Freie, und diese ist unsere Mutter.',
        27: 'Denn es steht geschrieben: Frohlocke, du Unfruchtbare, die nicht gebiert! Brich in Jubel aus du, die nicht kreißet; denn der Kinder der Einsamen sind viel mehr als der, die den Mann hat.',
        28: 'Wir aber, Brüder, sind dem Isaak nach der Verheißung Kinder.',
        29: 'Aber wie damals der nach dem Fleisch Geborene den nach dem Geist Geborenen verfolgte, so geht es auch jetzt.',
        30: 'Aber was sagt die Schrift? Treibe die Magd aus und ihren Sohn; denn der Sohn der Magd soll nicht erben mit dem Sohn der Freien!',
        31: 'So sind wir denn, Brüder, nicht Kinder der Magd, sondern der Freien.',
    },
    5: {
        1: 'So besteht nun in der Freiheit, die Christus für euch gewonnen hat, und lasset euch nicht wieder unter das Joch der Knechtschaft spannen.',
        2: 'Siehe ich, Paulus, sage euch, daß, wenn ihr euch beschneiden lasset, Christus euch nichts nützen wird.',
        3: 'Ich bezeuge abermals einem jeden, der sich beschneiden läßt, daß er verpflichtet ist, das ganze Gesetz zu halten.',
        4: 'Ihr alle, die ihr durch das Gesetz gerecht werden wollt, seid von Christus abgefallen und der Gnade verlustig geworden.',
        5: 'Denn wir harren vermöge des Geistes der Hoffnung auf Gerechtigkeit aus dem Glauben.',
        6: 'Denn in Jesus Christus gilt weder Beschneidung, noch Vorhaut, sondern der Glaube, der durch die Liebe tätig ist.',
        7: 'Ihr ward auf dem rechten Wege. Wer hat euch aufgehalten, daß ihr der Wahrheit nicht folgt?',
        8: 'Diese Überredung kommt nicht von Dem, Der euch berufen hat.',
        9: 'Ein wenig Sauerteig säuert schon den ganzen Teig.',
        10: 'Ich versehe mich zu euch in dem Herrn, daß ihr nicht anders gesinnt sein werdet. Wer euch aber irre macht, der wird die Schuld tragen, er sei, wer er wolle.',
        11: 'Ich aber, Brüder, wenn ich Beschneidung noch predige, warum werde ich noch verfolgt? Dann ist ja das Ärgernis des Kreuzes aufgehoben.',
        12: 'Ach möchten sie sich noch dazu verschneiden lassen, die euch so in Unruhe bringen!',
        13: 'Ihr seid ja zur Freiheit berufen, Brüder, nur nicht zur Freiheit, als zu einem Anlaß für das Fleisch, sondern daß einer durch Liebe dem anderen diene.',
        14: 'Denn das ganze Gesetz ist in einem Gebot enthalten, in dem: Du sollst deinen Nächsten lieben, wie dich selbst.',
        15: 'So ihr euch aber untereinander beißet und auffresset, so seht wohl zu, daß ihr nicht gar voneinander verschlungen werdet.',
        16: 'Ich meine aber: Wandelt im Geist, so werdet ihr die Begierde des Fleisches nicht vollbringen.',
        17: 'Denn das Fleisch gelüstet wider den Geist, und der Geist wider das Fleisch; dieselben streiten wider einander, daß ihr nicht tut, was ihr wollt.',
        18: 'Wenn ihr euch aber von dem Geist führen lasset, so seid ihr nicht unter dem Gesetz.',
        19: 'Offenbar aber sind die Werke des Fleisches, als da sind: Ehebruch, Hurerei, Unzucht, Schwelgerei,',
        20: 'Götzendienst, Zauberei, Feindschaft, Hader, Eifersucht, Leidenschaft, Streitsucht, Zwietracht, Parteisucht, Mißgunst, Mordsucht,',
        21: 'Zechen, Schwärmgelage und dergleichen, von denen ich euch vorhersage, und auch schon früher gesagt habe, daß die, welche solches tun, das Reich Gottes nicht ererben werden.',
        22: 'Die Frucht des Geistes aber ist Liebe, Freude, Friede, Langmut, Güte, Wohlwollen, Treue, Sanftmut, Enthaltsamkeit.',
        23: 'Wider solche ist das Gesetz nicht.',
        24: 'Die aber Christus angehören, haben das Fleisch gekreuzigt samt den Lüsten und Begierden.',
        25: 'So wir aber im Geist leben, so lasset uns auch im Geiste wandeln.',
        26: 'Lasset uns nicht nach eitler Ehre trachten, einander nicht aufreizen, einander nicht neiden!',
    },
    6: {
        1: 'Brüder, so jemand von einem Fehl übereilt wird, so bringt solchen ihr, die ihr geistig gesinnt seid, im Geiste der Sanftmut wieder zurecht, und siehe auf dich selbst, daß du nicht auch versucht werdest.',
        2: 'Einer trage des anderen Last, so werdet ihr Christus Gesetz erfüllen.',
        3: 'Denn so einer sich läßt dünken, er sei etwas, so er doch nichts ist, der betört sich selbst.',
        4: 'Ein jeder prüfe sein eigen Werk, und dann wird er sein Rühmen für sich und nicht für andere haben.',
        5: 'Denn ein jeglicher soll seine eigene Last tragen.',
        6: 'Gemeinschaft aber habe der, so in der Lehre unterrichtet wird, mit dem, der ihn unterrichtet, in allen Gütern.',
        7: 'Irrt euch nicht, Gott läßt Sich nicht spotten; denn was der Mensch sät, das wird er ernten.',
        8: 'Wer auf sein eigen Fleisch sät, der wird von dem Fleisch Verderben ernten. Wer aber auf den Geist sät, der wird von dem Geist ewiges Leben ernten.',
        9: 'Lasset uns aber im Gutestun nicht müde werden; denn zu seiner Zeit werden wir, wenn wir nicht laß werden, auch ernten.',
        10: 'Lasset uns denn, nun wir Zeit haben, allen Gutes tun, allermeist aber den Glaubensgenossen.',
        11: 'Seht, mit wie großen Buchstaben ich eigenhändig schreibe:',
        12: 'Diejenigen, die im Fleisch einen guten Anschein haben wollen, wollen euch die Beschneidung aufnötigen, nur um nicht wegen Christus Kreuz verfolgt zu werden.',
        13: 'Denn auch sie selbst, die sich beschneiden lassen, halten das Gesetz nicht, sondern wollen nur, daß ihr euch beschneiden lasset, auf daß sie sich eures Fleisches rühmen können.',
        14: 'Es sei aber ferne von mir, mich zu rühmen, denn allein des Kreuzes unseres Herrn Jesus Christus, durch Den mir die Welt gekreuzigt ist, und ich der Welt.',
        15: 'Denn in Jesus Christus gilt weder Beschneidung noch Vorhaut etwas, sondern die neue Schöpfung.',
        16: 'Und wie viele nach dieser Richtschnur wandeln, über die komme Friede und Erbarmen als über das Israel Gottes!',
        17: 'Hinfort mache mir niemand mehr Beschwerde, denn ich trage die Mahlzeichen des Herrn Jesus an meinem Leibe.',
        18: 'Die Gnade unseres Herrn Jesus Christus sei mit eurem Geiste, Brüder! Amen.',
    },
}
